using System;
using System.Collections.Generic;
using Astrea.GameElements;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MultipleSoulHeatTierAction", menuName = "Data/Battle/Battle Actions/Sothis/MultipleSoulHeatTierAction")]
public class MultipleSoulHeatTierAction : MinimumSoulHeatBasedAction
{
	[Header("First Action")]
	[SerializeField]
	private bool disableBattleActionVariable;

	[SerializeField]
	[HideIf("disableBattleActionVariable")]
	protected BattleAction battleAction;

	[SerializeField]
	[HideIf("enableVariableActionSoulHeatAmountToUse")]
	protected bool variableActionValue;

	[SerializeField]
	[HideIf("variableActionValue")]
	private bool enableVariableActionSoulHeatAmountToUse;

	[SerializeField]
	[HideIf("hideActionValue")]
	protected int actionValue;

	[SerializeField]
	private bool checkDecreaseSoulHeatOnFirstAction;

	[Header("Second Action")]
	[SerializeField]
	private bool increaseSoulHeatOnSecondAction;

	[SerializeField]
	private bool disableSecondBattleActionVariable;

	[SerializeField]
	[HideIf("disableSecondBattleActionVariable")]
	protected BattleAction secondBattleAction;

	[SerializeField]
	protected int secondActionValue;

	[SerializeField]
	protected int secondActionSoulHeatAmountToUse;

	[Header("Third Action")]
	[SerializeField]
	private bool disableThirdAction;

	[SerializeField]
	[HideIf("disableThirdAction")]
	protected BattleAction thirdBattleAction;

	[SerializeField]
	[HideIf("disableThirdAction")]
	protected int thirdActionValue;

	[SerializeField]
	[HideIf("increaseSoulHeatByFixedAmountOnThirdAction")]
	private bool increaseSoulHeatBySecondActionSoulHeatAmountOnThirdAction;

	[SerializeField]
	[HideIf("increaseSoulHeatBySecondActionSoulHeatAmountOnThirdAction")]
	private bool increaseSoulHeatByFixedAmountOnThirdAction;

	[SerializeField]
	[ShowIf("increaseSoulHeatByFixedAmountOnThirdAction")]
	private int soulHeatIncreaseFixedAmountOnThirdAction;

	[Header("Decrease Soul Heat Second and Third Action")]
	[SerializeField]
	private bool checkDecreaseSoulHeatOnFirstAndSecondAction;

	[Header("Ignore Check Decrease Soul Heat")]
	[SerializeField]
	private bool ignoreCheckDecreaseSoulHeatOnAnyAction;

	public bool DisableBattleActionVariable => disableBattleActionVariable;

	public BattleAction BattleAction => battleAction;

	private bool hideActionValue
	{
		get
		{
			if (!variableActionValue)
			{
				return enableVariableActionSoulHeatAmountToUse;
			}
			return true;
		}
	}

	public bool VariableActionValue => variableActionValue;

	public bool EnableVariableActionSoulHeatAmountToUse => enableVariableActionSoulHeatAmountToUse;

	public int ActionValue => actionValue;

	public bool CheckDecreaseSoulHeatOnFirstAction => checkDecreaseSoulHeatOnFirstAction;

	public bool IncreaseSoulHeatOnSecondAction => increaseSoulHeatOnSecondAction;

	public bool DisableSecondBattleActionVariable => disableSecondBattleActionVariable;

	public BattleAction SecondBattleAction => secondBattleAction;

	public int SecondActionValue => secondActionValue;

	public int SecondActionSoulHeatAmountToUse => secondActionSoulHeatAmountToUse;

	public bool DisableThirdAction => disableThirdAction;

	public BattleAction ThirdBattleAction => thirdBattleAction;

	public int ThirdActionValue => thirdActionValue;

	public bool IncreaseSoulHeatBySecondActionSoulHeatAmountOnThirdAction => increaseSoulHeatBySecondActionSoulHeatAmountOnThirdAction;

	public bool IncreaseSoulHeatByFixedAmountOnThirdAction => increaseSoulHeatByFixedAmountOnThirdAction;

	public int SoulHeatIncreaseFixedAmountOnThirdAction => soulHeatIncreaseFixedAmountOnThirdAction;

	public bool CheckDecreaseSoulHeatOnFirstAndSecondAction => checkDecreaseSoulHeatOnFirstAndSecondAction;

	public override DiceActionLogic GetDiceActionLogic(int actionValue = -1)
	{
		int soulHeatAmountToUse = GetSoulHeatAmountToUse(activateFeedback: false);
		if (soulHeatAmountToUse >= 10)
		{
			return diceActionLogic;
		}
		if (soulHeatAmountToUse >= secondActionSoulHeatAmountToUse)
		{
			if (secondBattleAction == null)
			{
				return diceActionLogic;
			}
			return secondBattleAction.GetDiceActionLogic(actionValue);
		}
		return thirdBattleAction.GetDiceActionLogic(actionValue);
	}

	protected void CastMultipleSoulHeatTierAction(Action firstTierAction, Action secondTierAction, Action thirdTierAction, GameObject source)
	{
		int soulHeatAmountToUseAndDecreaseEffect = GetSoulHeatAmountToUseAndDecreaseEffect();
		if (soulHeatAmountToUseAndDecreaseEffect >= 10)
		{
			firstTierAction();
			if ((checkDecreaseSoulHeatOnFirstAction && !ignoreCheckDecreaseSoulHeatOnAnyAction) || checkDecreaseSoulHeatOnFirstAndSecondAction)
			{
				CheckDecreaseSoulHeat();
			}
		}
		else if (soulHeatAmountToUseAndDecreaseEffect >= secondActionSoulHeatAmountToUse)
		{
			if (increaseSoulHeatOnSecondAction)
			{
				ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
				soulHeat.ModifySoulHeat(secondActionValue);
				CheckCancelAutoOnDiceCastedOnRuneCasted(source);
				ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
			}
			else
			{
				secondTierAction();
				if (checkDecreaseSoulHeatOnFirstAndSecondAction)
				{
					CheckDecreaseSoulHeat();
				}
			}
		}
		else
		{
			thirdTierAction();
			if (increaseSoulHeatBySecondActionSoulHeatAmountOnThirdAction)
			{
				soulHeat.ModifySoulHeat(secondActionSoulHeatAmountToUse);
			}
			else if (increaseSoulHeatByFixedAmountOnThirdAction)
			{
				soulHeat.ModifySoulHeat(soulHeatIncreaseFixedAmountOnThirdAction);
			}
		}
		if (!checkDecreaseSoulHeatOnFirstAction && !ignoreCheckDecreaseSoulHeatOnAnyAction && !checkDecreaseSoulHeatOnFirstAndSecondAction)
		{
			CheckDecreaseSoulHeat();
		}
	}

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		CastMultipleSoulHeatTierAction(delegate
		{
			battleAction.AreaCastTargetAmount(targets, actionValue, source);
		}, delegate
		{
			secondBattleAction.AreaCastTargetAmount(targets, secondActionValue, source);
		}, delegate
		{
			thirdBattleAction.AreaCastTargetAmount(targets, thirdActionValue, source);
		}, source);
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		CastMultipleSoulHeatTierAction(delegate
		{
			battleAction.CastTargetAmount(target, actionValue, source);
		}, delegate
		{
			secondBattleAction.CastTargetAmount(target, secondActionValue, source);
		}, delegate
		{
			thirdBattleAction.CastTargetAmount(target, thirdActionValue, source);
		}, source);
	}

	public override void Cast(GameObject source)
	{
		CastMultipleSoulHeatTierAction(delegate
		{
			battleAction.CastAmount(actionValue, source);
		}, delegate
		{
			secondBattleAction.CastAmount(secondActionValue, source);
		}, delegate
		{
			thirdBattleAction.CastAmount(thirdActionValue, source);
		}, source);
	}

	public void CastMultipleSoulHeatTierFirstActionSoulHeatVariableAction(Action firstTierAction, Action secondTierAction, Action thirdTierAction, int variableSoulHeat, GameObject source)
	{
		int soulHeatAmountToUseAndDecreaseEffect = GetSoulHeatAmountToUseAndDecreaseEffect();
		if (soulHeatAmountToUseAndDecreaseEffect >= variableSoulHeat)
		{
			firstTierAction();
			if (checkDecreaseSoulHeatOnFirstAction)
			{
				CheckDecreaseSoulHeat();
			}
		}
		else if (soulHeatAmountToUseAndDecreaseEffect >= secondActionSoulHeatAmountToUse)
		{
			if (increaseSoulHeatOnSecondAction)
			{
				ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
				soulHeat.ModifySoulHeat(secondActionValue);
				CheckCancelAutoOnDiceCastedOnRuneCasted(source);
				ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
			}
			else
			{
				secondTierAction();
			}
		}
		else
		{
			thirdTierAction();
		}
		if (!checkDecreaseSoulHeatOnFirstAction)
		{
			CheckDecreaseSoulHeat();
		}
	}
}
